html:
{%- set b = get_recipe_branding() -%}
<style>
 .hk-dn { font-family: "Open Sans", Arial, "PingFang HK", "Microsoft JhengHei", sans-serif; color: #211f20; font-size: 12px; line-height: 1.45; }
 .hk-dn h2 { font-family: Oswald, Arial, sans-serif; font-weight: 600; font-size: 20px; margin: 0; color: {{ b.primary_color }}; }
 .hk-dn .eyebrow { font-size: 10px; font-weight: 600; letter-spacing: 1.5px; text-transform: uppercase; color: {{ b.primary_color }}; }
 .hk-dn .head { width: 100%; border-collapse: collapse; margin-bottom: 12px; }
 .hk-dn .head td { border: 0; padding: 0; vertical-align: top; }
 .hk-dn .logo { max-height: 56px; max-width: 180px; }
 .hk-dn table.grid { width: 100%; border-collapse: collapse; margin-top: 10px; }
 .hk-dn table.grid th, .hk-dn table.grid td { border: 1px solid #c9bdb8; padding: 5px 7px; text-align: left; vertical-align: top; }
 .hk-dn table.grid th { background: #f8f2f1; font-weight: 600; white-space: nowrap; }
 .hk-dn .num { text-align: right; white-space: nowrap; }
 .hk-dn small { color: #5e5e5e; }
 .hk-dn .sig { width: 100%; margin-top: 48px; border-collapse: separate; border-spacing: 32px 0; }
 .hk-dn .sig td { border-top: 1px solid #211f20; padding-top: 4px; width: 50%; }
 .hk-dn .foot { margin-top: 18px; color: #5e5e5e; font-size: 10px; }
</style>
<div class="hk-dn">
 <table class="head"><tr>
  <td>
   {% if b.brand_logo %}<img class="logo" src="{{ b.brand_logo }}"><br>{% endif %}
   <h2>{{ b.brand_name or doc.company }}</h2>
   {% if doc.company_address_display %}<small>{{ doc.company_address_display | striptags }}</small>{% endif %}
  </td>
  <td style="text-align:right">
   <div class="eyebrow">送貨單 · Delivery Note</div>
   <h2>{{ doc.name }}</h2>
   {% if doc.docstatus == 0 %}<small>DRAFT 草稿</small>{% endif %}
  </td>
 </tr></table>
 <table class="grid">
  <tr><th>客戶 Client</th><td>{{ doc.customer_name }}{% if doc.customer_name != doc.customer %} <small>({{ doc.customer }})</small>{% endif %}</td>
      <th>日期 Date</th><td>{{ frappe.utils.formatdate(doc.posting_date) }}{% if doc.posting_time %} · {{ frappe.utils.format_time(doc.posting_time, "HH:mm") }}{% endif %}</td></tr>
  <tr><th>送貨地址 Deliver to</th><td>{{ (doc.shipping_address or doc.address_display or "") | striptags }}</td>
      <th>聯絡 Contact</th><td>{{ doc.contact_display or "" }}{% if doc.contact_mobile %}<br>{{ doc.contact_mobile }}{% endif %}</td></tr>
  <tr><th>客戶訂單 Client PO</th><td>{{ doc.po_no or "" }}</td>
      <th>司機 / 車牌 Driver / Vehicle</th><td>{{ doc.driver_name or "" }}{% if doc.vehicle_no %} · {{ doc.vehicle_no }}{% endif %}</td></tr>
 </table>
 <table class="grid">
  <thead><tr><th style="width:24px">#</th><th>編號 SKU</th><th>貨品 Item</th><th class="num">數量 Qty</th><th>單位 Unit</th><th>批號 Lot</th><th style="width:70px">已收 ✓</th></tr></thead>
  <tbody>
  {% for row in doc.items %}
   <tr>
    <td>{{ row.idx }}</td>
    <td>{{ row.item_code }}</td>
    <td>{{ row.item_name }}{% if row.description and (row.description | striptags) != row.item_name %}<br><small>{{ row.description | striptags | truncate(120) }}</small>{% endif %}</td>
    <td class="num">{{ row.get_formatted("qty") }}</td>
    <td>{{ row.uom }}</td>
    <td>{{ row.batch_no or "" }}</td>
    <td></td>
   </tr>
  {% endfor %}
  </tbody>
  <tfoot><tr><th colspan="3" class="num">合共 Total</th><th class="num">{{ doc.get_formatted("total_qty") }}</th><th colspan="3"></th></tr></tfoot>
 </table>
 {% if doc.instructions %}<p><b>備註 Notes:</b> {{ doc.instructions }}</p>{% endif %}
 <table class="sig"><tr><td>送貨人 Delivered by</td><td>收貨人簽署及公司印 Received by (signature and chop)</td></tr></table>
 {% if b.print_footer %}<div class="foot">{{ b.print_footer }}</div>{% endif %}
</div>
